import React from 'react';
import AppView from './generated/AppView.jsx';
import { api, auth, socket } from './api.js';
import { TODAY, MONTH_START, jAdd, jWeekday, jLong, WD_NAMES, jStr, pad as jpad } from './jalali.js';

// rolling window: 'yyyy/mm/dd HH:MM' of now minus 24 hours (comparable with call date + time)
const since24 = () => { const d = new Date(Date.now() - 24 * 3600e3); return jStr(d) + ' ' + jpad(d.getHours()) + ':' + jpad(d.getMinutes()); };

let ME = { id: '', name: '', ext: '', role: 'operator' };
let OPS = [];

const ROLE_LABEL = { admin: 'مدیر سامانه', supervisor: 'سرپرست مرکز تماس', operator: 'اپراتور', accounting: 'حسابداری', reception: 'پذیرش', emergency: 'پشتیبانی اضطراری' };
const DEPT_REF = { accounting: 'acc', reception: 'rec', emergency: 'emg' };
// Collections that mirror the Asterisk configuration; saved to /api/config/:key (admin only).
const VOIP_KEYS = ['oroutes', 'routes', 'tgroups', 'holidays', 'tconds', 'rgroups', 'fmes', 'blist', 'bset', 'exts', 'trunks', 'vqs', 'ivrs', 'snds'];
// Live fields come from AMI and are never written back.
const LIVE_FIELDS = { exts: ['st'], vqs: ['waiting', 'sla'], trunks: ['reg', 'used'] };
const WORKFLOW_KEYS = ['follow', 'doneAt', 'notes'];

const strip = (k, v) => {
  const f = LIVE_FIELDS[k];
  if (!f || !Array.isArray(v)) return v;
  return v.map(x => { const y = { ...x }; f.forEach(n => delete y[n]); return y; });
};

class LiveApp extends React.Component {
  synced = {};
  saveT = {};
  remote = false;

  init() {
    const b = this.props.boot;
    ME = { ...b.me };
    OPS = b.operators;
    this.applyBoot(b);
    this.audio = new Audio();
    this.audio.preload = 'auto';
    this.audio.onended = () => this.setState({ paused: true });
    this.audio.onloadedmetadata = () => { this.audDur = this.audio.duration; };
    this.tick = setInterval(() => {
      if (this.state.pid && !this.audio.paused) this.setState({ pos: this.audio.currentTime });
    }, 200);
    this.sock = socket();
    this.sock.on('live', l => this.applyLive(l));
    this.sock.on('calls', () => this.reloadCalls());
    this.sock.on('workflow', w => this.applyRemote(w));
    this.sock.on('config', c => { if (c.by !== ME.id) this.applyRemote({ [c.key]: c.data }); });
    this.sock.on('cb', e => this.onCallback(e));
    this.sock.on('notify', n => this.toast(n.text));
    window.addEventListener('beforeunload', this.flush);
  }

  teardown() {
    clearInterval(this.tick);
    clearInterval(this.callT);
    this.audio && this.audio.pause();
    this.sock && this.sock.disconnect();
    window.removeEventListener('beforeunload', this.flush);
  }

  applyBoot(b) {
    this.calls = b.calls.map(enrich);
    const st = { ...b.config, ...b.workflow };
    VOIP_KEYS.forEach(k => { this.synced[k] = JSON.stringify(strip(k, st[k])); });
    WORKFLOW_KEYS.forEach(k => { this.synced[k] = { ...(st[k] || {}) }; });
    this.remote = true;
    this.setState({ ...st, selRoute: (st.routes[0] || {}).id, selIvr: (st.ivrs[0] || {}).id, selFm: (st.exts.find(e => st.fmes[e.n]) || st.exts[0] || {}).n }, () => { this.remote = false; });
  }

  applyRemote(patch) {
    const next = {};
    Object.entries(patch).forEach(([k, v]) => {
      if (VOIP_KEYS.includes(k)) { this.synced[k] = JSON.stringify(strip(k, v)); next[k] = v; }
      if (WORKFLOW_KEYS.includes(k)) { Object.assign(this.synced[k], v); next[k] = { ...this.state[k], ...v }; }
    });
    this.remote = true;
    this.setState(next, () => { this.remote = false; });
  }

  applyLive(l) {
    this.remote = true;
    this.setState(st => ({
      exts: st.exts.map(e => l.exts && l.exts[e.n] ? { ...e, ...l.exts[e.n] } : { ...e, st: 'offline' }),
      vqs: st.vqs.map(q => l.queues && l.queues[q.id] ? { ...q, ...l.queues[q.id] } : q),
      trunks: st.trunks.map(t => l.trunks && l.trunks[t.id] ? { ...t, ...l.trunks[t.id] } : t),
    }), () => { this.remote = false; });
  }

  async reloadCalls() {
    clearTimeout(this.reloadT);
    this.reloadT = setTimeout(async () => {
      try {
        const r = await api('/calls');
        this.calls = r.calls.map(enrich);
        this.forceUpdate();
      } catch (e) { /* the next event retries */ }
    }, 300);
  }

  componentDidUpdate(prevProps, prev) {
    const s = this.state;
    if (this.audio) {
      if (this.audio.playbackRate !== s.speed) this.audio.playbackRate = s.speed;
      if (s.pid && Math.abs(this.audio.currentTime - s.pos) > 0.6) this.audio.currentTime = s.pos;
      if (s.pid && s.paused && !this.audio.paused) this.audio.pause();
      if (!s.pid && prev.pid) { this.audio.pause(); this.audDur = 0; }
    }
    if (prev.call && prev.call.origId && !s.call && !this.endingCall) api('/calls/hangup', { origId: prev.call.origId }).catch(() => {});
    if (s.page === 'vapi' && prev.page !== 'vapi') this.loadApi();
    if (this.remote) return;
    VOIP_KEYS.forEach(k => {
      if (s[k] === prev[k]) return;
      const json = JSON.stringify(strip(k, s[k]));
      if (json === this.synced[k]) return;
      clearTimeout(this.saveT[k]);
      this.saveT[k] = setTimeout(() => this.saveConfig(k, json), 700);
    });
    WORKFLOW_KEYS.forEach(k => {
      if (s[k] === prev[k]) return;
      const changed = {};
      Object.entries(s[k] || {}).forEach(([id, v]) => { if (JSON.stringify(v) !== JSON.stringify(this.synced[k][id])) changed[id] = v; });
      if (!Object.keys(changed).length) return;
      Object.assign(this.synced[k], changed);
      api('/workflow', { [k]: changed }).catch(e => this.toast('ذخیره پیگیری ناموفق بود: ' + e.message));
    });
  }

  flush = () => { Object.keys(this.saveT).forEach(k => clearTimeout(this.saveT[k])); };

  async saveConfig(k, json) {
    try {
      const r = await api('/config/' + k, { data: JSON.parse(json) }, 'PUT');
      this.synced[k] = JSON.stringify(strip(k, r.data));
      if (JSON.stringify(strip(k, r.data)) !== json) this.applyRemote({ [k]: mergeLive(k, r.data, this.state[k]) });
      if (r.applied === false) this.toast('ذخیره شد ولی اعمال در مرکز تلفن ناموفق بود: ' + (r.error || ''));
    } catch (e) {
      this.toast('ذخیره تنظیمات ناموفق بود: ' + e.message);
    }
  }

  // Outbound routes page (not in the original design; built in the same visual language).
  voipOut(s) {
    const list = s.oroutes || [];
    const upd = fn => this.setState(st => ({ oroutes: fn(st.oroutes || []) }));
    const u = (id, k, v) => upd(l => l.map(x => x.id === id ? { ...x, [k]: v } : x));
    const tg = on => ({ bg: on ? '#8DC63F' : '#d9dad6', j: on ? 'flex-end' : 'flex-start' });
    const tname = id => (s.trunks.find(t => t.id === id) || { name: '—' }).name;
    const move = (i, d) => upd(l => { const a = [...l]; const j = i + d; if (j < 0 || j >= a.length) return l; [a[i], a[j]] = [a[j], a[i]]; return a; });
    const num = String(s.oTest || '').replace(/[^0-9*#+]/g, '');
    let res = { t: 'یک شماره وارد کنید', bg: '#fff', fg: '#6b6e72', bd: '#e1e3dc' };
    if (num) {
      const hit = matchOutbound(list, num);
      res = hit ? { t: 'مسیر «' + hit.route.name + '» ← ترانک ' + tname(hit.route.trunk) + ' ← شماره ارسالی: ' + hit.dial, bg: '#8DC63F', fg: '#1f2021', bd: '#8DC63F' }
        : { t: 'هیچ مسیر فعالی با این شماره منطبق نیست؛ تماس برقرار نمی‌شود', bg: '#fdeceb', fg: '#b42318', bd: '#f5c2bd' };
    }
    return { vo: {
      test: s.oTest || '', setTest: e => this.setState({ oTest: e.target.value }), res, empty: !list.length,
      trunks: s.trunks.map(t => ({ id: t.id, label: t.name + (t.on ? '' : ' (غیرفعال)') })),
      add: () => upd(l => [...l, { id: 'o' + Date.now(), name: 'مسیر خروجی جدید', pats: '.', trunk: (s.trunks.find(t => t.on) || s.trunks[0] || {}).id || '', prepend: '', on: true }]),
      rows: list.map((r, i) => ({
        ...r, idx: i + 1, op: r.on ? 1 : .55, onT: tg(r.on), tog: () => u(r.id, 'on', !r.on),
        setName: e => u(r.id, 'name', e.target.value), setPats: e => u(r.id, 'pats', e.target.value), setTrunk: e => u(r.id, 'trunk', e.target.value),
        setPrepend: e => u(r.id, 'prepend', e.target.value.replace(/[^0-9*#+]/g, '')),
        up: () => move(i, -1), down: () => move(i, 1), del: () => { upd(l => l.filter(x => x.id !== r.id)); this.toast('مسیر خروجی حذف شد'); },
        sum: 'شماره‌های ' + (r.pats || '—') + ' از ترانک ' + tname(r.trunk) + (r.prepend ? ' با پیش‌شماره ' + r.prepend : ''),
      })),
    } };
  }

  async exportXlsx(list, title, f) {
    if (!list.length) { this.toast('تماسی برای خروجی گرفتن وجود ندارد'); return; }
    this.toast('در حال ساخت فایل Excel (' + list.length + ' تماس)…');
    try {
      const blob = await api.blob('/calls/export', { ids: list.map(c => c.id), title, from: f.from, to: f.to, kind: title === 'تماس‌های بی‌پاسخ' ? 'missed' : title === 'پیگیری‌نشده‌ها' ? 'unreached' : 'all' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = title + ' ' + f.from.replace(/\//g, '-') + ' تا ' + f.to.replace(/\//g, '-') + '.xlsx';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 10000);
    } catch (e) { this.toast('ساخت فایل ناموفق بود: ' + e.message); }
  }

  async exportReport(payload) {
    if (!payload.total) { this.toast('در این بازه و با این فیلترها تماسی برای گزارش وجود ندارد'); return; }
    this.toast('در حال ساخت فایل Excel گزارش…');
    try {
      const blob = await api.blob('/reports/export', payload);
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = payload.title + ' ' + payload.from.replace(/\//g, '-') + ' تا ' + payload.to.replace(/\//g, '-') + '.xlsx';
      document.body.appendChild(a); a.click(); a.remove();
      setTimeout(() => URL.revokeObjectURL(a.href), 10000);
    } catch (e) { this.toast('ساخت فایل گزارش ناموفق بود: ' + e.message); }
  }

  // phone -> time of the latest conversation (answered inbound/transfer, or answered outbound/callback)
  contactIndex(C) {
    if (this._ciC === C) return this._ci;
    const m = {};
    for (const c of C) {
      const ok = c.dir === 'in' ? (c.st === 'answered' || c.st === 'transferred') : c.st === 'answered';
      if (!ok) continue;
      const w = c.date + ' ' + c.time;
      if (!m[c.phoneRaw] || m[c.phoneRaw] < w) m[c.phoneRaw] = w;
    }
    this._ciC = C; this._ci = m;
    return m;
  }

  // Callers in the date range who called and never got to talk to the clinic since (one row per number).
  unreachedVals(C, cF, q, isUR, lastOk, limit = 8) {
    const s = this.state;
    const qq = (q || '').replace(/\s/g, '');
    // mobiles only (09xxxxxxxxx): landlines and short/unknown numbers are left out of this list
    const att = C.filter(c => isUR(c) && /^09\d{9}$/.test(c.phoneRaw) && c.date >= cF.from && c.date <= cF.to && (!cF.since || c.date + ' ' + c.time >= cF.since) && (!q || c.name.includes(q) || c.phoneRaw.includes(qq)));
    const by = {};
    for (const c of att) (by[c.phoneRaw] = by[c.phoneRaw] || []).push(c);
    const when = c => c.date + ' ' + c.time;
    const stage = c => c.short ? 'مکالمه زیر ۵ ثانیه' : c.st === 'voicemail' ? 'پیام صوتی گذاشت' : /Night|شب/.test(c.queue) ? 'منوی شب' : /^IVR/.test(c.queue) ? 'منوی روز' : 'در صف';
    const groups = Object.entries(by).map(([p, l]) => {
      l.sort((a, b) => when(a).localeCompare(when(b)));
      const f0 = l[0], last = l[l.length - 1];
      const since = lastOk[p] || '';
      const cbs = C.filter(x => x.dir === 'out' && x.phoneRaw === p && when(x) > when(f0) && when(x) > since);
      return { p, l, f0, last, cbs };
    }).sort((a, b) => b.l.length - a.l.length || when(b.last).localeCompare(when(a.last)));
    const all = !!s.urAll;
    const shown = all ? groups : groups.slice(0, limit);
    return {
      count: groups.length, range: cF.since ? '۲۴ ساعت گذشته' : cF.from === cF.to ? cF.from : cF.from + ' تا ' + cF.to, has: groups.length > 0, empty: !groups.length,
      groups, more: groups.length > limit, toggle: () => this.setState({ urAll: !all }), toggleText: all ? 'نمایش کمتر' : 'نمایش همه (' + groups.length + ' شماره)',
      export: () => this.exportXlsx(groups.flatMap(g => g.l), 'پیگیری‌نشده‌ها', cF),
      rows: shown.map(g => ({
        name: g.last.known ? g.last.name : 'شماره ناشناس', ini: g.last.ini, phone: g.last.phone, attempts: g.l.length,
        firstDate: g.f0.date, firstTime: g.f0.time, lastDate: g.last.date, lastTime: g.last.time, lastStage: stage(g.last),
        cbText: g.cbs.length ? g.cbs.length + ' بار تماس گرفته شد، جواب نداد' : 'هنوز تماسی گرفته نشده', cbFg: g.cbs.length ? '#8a5a00' : '#b42318',
        openFile: () => this.openFile(g.last), call: () => this.startCall({ name: g.last.known ? g.last.name : g.last.phone, phone: g.last.phone, phoneRaw: g.p, vmId: null }),
      })),
    };
  }

  // «پیگیری‌نشده‌ها» page: own date range + search
  unreachedPage(C, isUR, lastOk) {
    const s = this.state;
    const w24 = () => { const c = since24(); return { from: c.slice(0, 10), to: TODAY, since: c, mode: '24h' }; };
    const f = s.uF || w24();
    const setF = o => this.setState({ uF: { ...f, since: null, mode: null, ...o }, urAll: false });
    const v = this.unreachedVals(C, f, s.uQ || '', isUR, lastOk, 30);
    const pill = on => ({ bg: on ? '#2E2F31' : '#fff', fg: on ? '#fff' : '#3a3b3d', bd: on ? '#2E2F31' : '#e1e3dc' });
    const QD = [['امروز', TODAY, TODAY], ['دیروز', jAdd(-1), jAdd(-1)], ['۷ روز اخیر', jAdd(-6), TODAY], ['این ماه', MONTH_START, TODAY]];
    const navCount = this.unreachedVals(C, w24(), '', isUR, lastOk, 0).count;
    const attempts = v.groups.reduce((n, g) => n + g.l.length, 0);
    const noCb = v.groups.filter(g => !g.cbs.length).length;
    return {
      ...v, f, q: s.uQ || '', setQ: e => this.setState({ uQ: e.target.value, urAll: false }),
      pick: { from: x => setF({ from: x }), to: x => setF({ to: x }) },
      navCount,
      quick: [{ label: '۲۴ ساعت گذشته', onClick: () => this.setState({ uF: w24(), urAll: false }), ...pill(f.mode === '24h') },
        ...QD.map(([label, a, b]) => ({ label, onClick: () => setF({ from: a, to: b }), ...pill(!f.mode && f.from === a && f.to === b) }))],
      kpis: [
        { value: v.count, label: 'شماره بدون ارتباط', bg: '#fdeceb', fg: '#e0574a', color: '#b42318' },
        { value: attempts, label: 'تلاش ناموفق برای تماس', bg: '#fbf1dc', fg: '#e0a83a', color: '#232425' },
        { value: noCb, label: 'هنوز با آن‌ها تماس گرفته نشده', bg: '#fdeceb', fg: '#b42318', color: '#b42318' },
        { value: v.count - noCb, label: 'تماس برگشتی گرفته شد ولی جواب ندادند', bg: '#e5eff7', fg: '#5b9bd0', color: '#232425' },
      ],
    };
  }

  // ---- «تنظیمات API»: webhook settings + delivery log
  async loadApi() {
    try {
      const d = await api('/webhook');
      this.setState({ apiData: d, apiForm: { enabled: d.settings.enabled, url: d.settings.url, headerName: d.settings.headerName, token: '', timeoutSec: d.settings.timeoutSec } });
    } catch (e) { this.toast('بارگذاری تنظیمات API ناموفق بود: ' + e.message); }
  }

  apiVals(s) {
    const d = s.apiData;
    const f = s.apiForm || { enabled: false, url: '', headerName: 'Authorization', token: '', timeoutSec: 10 };
    const setF = o => this.setState({ apiForm: { ...f, ...o } });
    const tg = on => ({ bg: on ? '#8DC63F' : '#d9dad6', j: on ? 'flex-end' : 'flex-start' });
    const fa = n => String(n).replace(/\d/g, x => '۰۱۲۳۴۵۶۷۸۹'[x]);
    const when = iso => { const t = new Date(iso); return jStr(t) + ' · ' + jpad(t.getHours()) + ':' + jpad(t.getMinutes()) + ':' + jpad(t.getSeconds()); };
    const tr = s.apiTest;
    const save = async () => {
      try {
        const r = await api('/webhook', f, 'PUT');
        this.setState(st => ({ apiData: { ...(st.apiData || {}), settings: r }, apiForm: { ...f, token: '' } }));
        this.toast(r.enabled ? 'تنظیمات API ذخیره شد؛ تماس‌ها از این به بعد ارسال می‌شوند' : 'تنظیمات API ذخیره شد (ارسال خاموش است)');
      } catch (e) { this.toast('ذخیره ناموفق بود: ' + e.message); }
    };
    return { api: {
      f, onT: tg(f.enabled), onLabel: f.enabled ? 'فعال' : 'غیرفعال', tog: () => setF({ enabled: !f.enabled }),
      set: Object.fromEntries(['url', 'headerName', 'token', 'timeoutSec'].map(k => [k, e => setF({ [k]: e.target.value })])),
      tokenPh: d && d.settings.hasToken ? 'ذخیره‌شده (' + d.settings.tokenHint + ') — برای تغییر، مقدار جدید بنویسید' : 'مثلاً Bearer abc123',
      save,
      test: async () => {
        this.setState({ apiTest: { t: 'در حال ارسال تست…', bg: '#fff', fg: '#6b6e72', bd: '#e1e3dc' } });
        try {
          if (JSON.stringify({ ...f, token: '' }) !== JSON.stringify({ ...(s.apiForm || {}), token: '' }) || f.token) await api('/webhook', f, 'PUT');
          const r = await api('/webhook/test', {});
          this.setState({ apiTest: r.ok ? { t: '✓ ارسال موفق · کد ' + r.code + ' · ' + r.ms + 'ms', bg: '#eaf4dc', fg: '#3d6a0c', bd: '#cfe4ad' } : { t: '✕ ' + r.error, bg: '#fdeceb', fg: '#b42318', bd: '#f5c2bd' } });
        } catch (e) { this.setState({ apiTest: { t: '✕ ' + e.message, bg: '#fdeceb', fg: '#b42318', bd: '#f5c2bd' } }); }
        this.loadApi();
      },
      hasTest: !!tr, testRes: tr || {},
      reload: () => this.loadApi(),
      kpis: [
        { value: d ? d.sent24 : '…', label: 'ارسال موفق در ۲۴ ساعت گذشته', bg: '#eaf4dc', fg: '#8DC63F', color: '#3d6a0c' },
        { value: d ? d.failed24 : '…', label: 'تلاش ناموفق در ۲۴ ساعت گذشته', bg: '#fdeceb', fg: '#e0574a', color: d && d.failed24 ? '#b42318' : '#232425' },
        { value: d ? (d.settings.enabled ? 'فعال' : 'غیرفعال') : '…', label: 'وضعیت ارسال خودکار', bg: '#e5eff7', fg: '#5b9bd0', color: d && d.settings.enabled ? '#3d6a0c' : '#8b8e89' },
      ],
      sample: d && d.sample ? JSON.stringify(d.sample, null, 2) : 'هنوز تماسی ثبت نشده است.',
      empty: !(d && d.rows.length),
      rows: (d ? d.rows : []).map(l => ({
        when: when(l.at), callId: l.callId, attempt: fa(l.attempt), label: l.ok ? 'موفق' : 'ناموفق', bg: l.ok ? '#eaf4dc' : '#fdeceb', fg: l.ok ? '#3d6a0c' : '#b42318',
        code: l.httpCode ? String(l.httpCode) : '—', ms: fa(l.ms) + ' ms', error: l.error || '', canResend: l.callId !== 'test',
        resend: async () => {
          try { const r = await api('/webhook/resend/' + encodeURIComponent(l.callId), {}); this.toast(r.ok ? 'تماس ' + l.callId + ' دوباره ارسال شد' : 'ارسال دوباره ناموفق بود: ' + r.error); }
          catch (e) { this.toast('ارسال دوباره ناموفق بود: ' + e.message); }
          this.loadApi();
        },
      })),
    } };
  }

  meVals() {
    const self = (this.state.exts || []).find(e => e.n === ME.ext);
    return {
      name: ME.name, ini: ini(ME.name), roleLabel: ROLE_LABEL[ME.role] || ME.role, extText: ME.ext ? ' · داخلی ' + ME.ext : '',
      dot: self && self.st !== 'offline' ? '#8DC63F' : '#b9bbb6', isAdmin: ME.role === 'admin',
      hasAlert: this.calls.some(c => c.st === 'voicemail' && (this.state.follow[c.id] || c.follow) === 'new'),
      logout: () => auth.logout(),
    };
  }

  deptOk(c, s) {
    const ref = DEPT_REF[ME.role];
    return !ref || (s.notes[c.id] || []).some(n => n.ref === ref);
  }

  // ---- audio ----
  playCall(id) {
    const s = this.state;
    const c = this.calls.find(x => x.id === id);
    if (!c || !c.hasVoice) return;
    if (this.sndA) { this.sndA.pause(); this.sndA = null; this.setState({ sndPlay: null }); }
    if (s.pid === id) {
      if (this.audio.paused) { if (this.audio.ended) this.audio.currentTime = 0; this.audio.play(); this.setState({ paused: false }); }
      else { this.audio.pause(); this.setState({ paused: true }); }
      return;
    }
    this.audDur = 0;
    this.audio.src = api.url('/recordings/' + encodeURIComponent(id));
    this.audio.playbackRate = s.speed;
    this.audio.play().catch(() => this.toast('پخش فایل ضبط ممکن نشد'));
    this.setState({ pid: id, pos: 0, paused: false });
  }

  download(c) {
    const a = document.createElement('a');
    a.href = api.url('/recordings/' + encodeURIComponent(c.id), { download: 1 });
    a.download = c.id + '.wav';
    document.body.appendChild(a); a.click(); a.remove();
  }

  playSound(x) {
    if (this.sndA) { this.sndA.pause(); this.sndA = null; }
    if (this.state.sndPlay === x.id) { this.setState({ sndPlay: null }); return; }
    if (this.state.pid && !this.state.paused) { this.audio.pause(); this.setState({ paused: true }); }
    this.sndA = new Audio(api.url('/sounds/' + encodeURIComponent(x.id) + '/file'));
    this.sndA.onended = () => this.setState({ sndPlay: null });
    this.sndA.play().catch(() => this.toast('پخش فایل صوتی ممکن نشد'));
    this.setState({ sndPlay: x.id });
  }

  async uploadSound(file, cat) {
    const fd = new FormData();
    fd.append('file', file);
    fd.append('cat', cat);
    this.toast('در حال بارگذاری و تبدیل «' + file.name + '»…');
    try {
      const r = await api('/sounds', fd);
      this.applyRemote({ snds: r.snds });
      this.toast('فایل «' + r.sound.name + '» بارگذاری و به فرمت مرکز تلفن تبدیل شد');
    } catch (e) { this.toast('بارگذاری ناموفق بود: ' + e.message); }
  }

  async testTrunk(t) {
    this.setState(st => ({ trTest: { ...st.trTest, [t.id]: 'در حال تست اتصال…' } }));
    let text;
    try {
      const r = await api('/trunks/' + encodeURIComponent(t.id) + '/test', {});
      text = r.ok ? '✓ اتصال موفق · تأخیر ' + r.ms + 'ms' : '✕ ' + r.error;
    } catch (e) { text = '✕ ' + e.message; }
    this.setState(st => ({ trTest: { ...st.trTest, [t.id]: text } }));
  }

  // ---- click-to-call: operator's phone rings first, then the patient is dialled (AMI Originate) ----
  async originate(p) {
    if (!ME.ext) { this.toast('برای کاربر شما داخلی تعریف نشده است'); return; }
    this.setState({ call: { name: p.name, phone: p.phone, phoneRaw: p.phoneRaw, vmId: p.vmId || null, stage: 'dial', t0: 0, el: 0, rec: false, recErr: '', note: '' } });
    try {
      const r = await api('/calls/originate', { phone: p.phoneRaw, name: p.name, vmId: p.vmId || null });
      this.setState(st => st.call ? { call: { ...st.call, origId: r.origId, rec: true } } : null);
    } catch (e) {
      this.setState({ call: null });
      this.toast('برقراری تماس ممکن نشد: ' + e.message);
    }
  }

  onCallback(e) {
    const c = this.state.call;
    if (!c || c.origId !== e.origId) return;
    if (e.stage === 'live' && c.stage !== 'live') {
      clearInterval(this.callT);
      this.setState({ call: { ...c, stage: 'live', t0: Date.now(), el: 0 } });
      this.callT = setInterval(() => this.setState(s => s.call && s.call.stage === 'live' ? { call: { ...s.call, el: Math.floor((Date.now() - s.call.t0) / 1000) } } : null), 500);
    }
    if (e.stage === 'ended') this.finishCall(e.answered);
  }

  async hangupCall() {
    const c = this.state.call;
    if (!c) return;
    if (!c.origId) { this.setState({ call: null }); return; }
    this.endingCall = true;
    try { await api('/calls/hangup', { origId: c.origId, note: c.note || '' }); } catch (e) { /* already gone */ }
    setTimeout(() => { if (this.state.call && this.state.call.origId === c.origId) this.finishCall(c.stage === 'live'); }, 4000);
  }

  async finishCall(answered) {
    const c = this.state.call;
    if (!c) return;
    clearInterval(this.callT);
    this.endingCall = true;
    if ((c.note || '').trim()) api('/calls/summary', { origId: c.origId, note: c.note.trim() }).catch(() => {});
    this.setState({ call: null }, () => { this.endingCall = false; });
    this.toast(answered ? 'تماس با ' + c.name + ' ثبت شد و ضبط مکالمه ذخیره شد' : 'تماس بی‌پاسخ با ' + c.name + ' ثبت شد');
    this.reloadCalls();
  }

  render() {
    return <AppView vm={this.renderVals()} />;
  }
}

const mergeLive = (k, saved, cur) => {
  const f = LIVE_FIELDS[k];
  if (!f || !Array.isArray(saved)) return saved;
  const key = k === 'exts' ? 'n' : 'id';
  return saved.map(x => { const c = (cur || []).find(y => y[key] === x[key]); if (!c) return x; const y = { ...x }; f.forEach(n => { if (c[n] !== undefined) y[n] = c[n]; }); return y; });
};

// Issabel-style dial patterns: X N Z . [..], optional "strip|pattern".
export function patRegex(p) {
  return new RegExp('^' + p.toUpperCase().replace(/X/g, '[0-9]').replace(/Z/g, '[1-9]').replace(/N/g, '[2-9]').replace(/\./g, '.+') + '$');
}
export function matchOutbound(routes, num) {
  for (const r of routes) {
    if (!r.on) continue;
    for (const raw of String(r.pats || '').split(/[,،\s]+/).filter(Boolean)) {
      const [pre, pat] = raw.includes('|') ? raw.split('|') : ['', raw];
      if (num.startsWith(pre) && patRegex(pat).test(num.slice(pre.length))) return { route: r, dial: (r.prepend || '') + num.slice(pre.length) };
    }
  }
  return null;
}

const PENDING_AI = { id: 'none', name: 'در انتظار تحلیل', fg: '#55585c', bg: '#efefed', bar: '#b9bbb6' };

// Server rows -> the exact call shape the design logic expects (see build() in the design).
function enrich(c) {
  const cat = c.ai ? (CATS.find(x => x.id === c.ai.cat) || { ...PENDING_AI, id: c.ai.cat, name: c.ai.cat }) : null;
  let ai = c.ai ? { ...c.ai, cat } : null;
  if (!ai && c.st === 'voicemail') ai = { cat: PENDING_AI, tx: 'متن این پیام هنوز استخراج نشده است؛ سرویس تبدیل گفتار به متن پیکربندی نشده یا در صف پردازش است.', sum: ['در انتظار تحلیل هوش مصنوعی'], kw: [], urg: 'low', sent: 'neu', conf: 0, pending: true };
  const op = c.op || null;
  return {
    ...c, ini: ini(c.name), dirLabel: c.dir === 'in' ? 'ورودی' : 'خروجی', status: ST[c.st] || ST.missed, histTitle: c.short ? 'وصل شد ولی کمتر از ۵ ثانیه طول کشید (بی‌پاسخ حساب شد)' : c.callback ? (c.st === 'answered' ? 'تماس برگشتی برقرار شد' : 'تماس برگشتی بی‌پاسخ') : HIST[c.st],
    op, opName: op ? op.name : 'IVR', ext: op ? op.ext : '—', durText: c.dur ? fmt(c.dur) : '—', waitText: c.wait + ' ثانیه',
    hasVoice: !!c.hasRec, noVoice: !c.hasRec, ai, hasAi: !!(ai && !ai.pending), noAi: !(ai && !ai.pending),
    aiName: ai ? ai.cat.name : '', aiFg: ai ? ai.cat.fg : '', aiBg: ai ? ai.cat.bg : '',
    wave: c.wave && c.wave.length ? c.wave : Array.from({ length: 56 }, (_, i) => 8 + ((i * 37) % 26)),
  };
}
